    // `evidence` — never by reading `VERILOOP` here, which would break the closure-free
    // contract this region is sliced and executed under.
    emittedBy: 'loop',
    confirmPromptHash: evidence.confirmPromptHash || null,
    routing: evidence.routing || null,
    feature: evidence.feature,
    repo: evidence.repo,
    tier: evidence.tier,
    baseSha: stamps.baseSha,
    headSha: stamps.headSha,
    verdict: evidence.verdict,
    checks,
    baselineProbe: evidence.baselineProbe || null,
    screenshots,
    screenshotVerdict: shot ? shot.verdict : null,
    fixPasses: evidence.fixPasses,
    blockers: evidence.blockers || [],
    concerns: evidence.concerns || [],
    // resolve-to-clean's NAMED fields (D8). A future auto-merge predicate READS these;
    // it must never re-derive them. `rawConcerns` vs `confirmedConcerns` is the only
    // measurement of the lens sensor's own noise rate, so both are always recorded —
    // `confirmedConcerns` is null under `blockers` mode, where nothing was confirmed,
    // and a null is not a zero.
    resolveMode: evidence.resolveMode || 'blockers',
    rawConcerns: typeof evidence.rawConcerns === 'number' ? evidence.rawConcerns : (evidence.concerns || []).length,
    confirmedConcerns: typeof evidence.confirmedConcerns === 'number' ? evidence.confirmedConcerns : null,
    preExistingConcerns: evidence.preExistingConcerns || [],
    unverifiedConcerns: evidence.unverifiedConcerns || [],
    waivedConcerns: evidence.waivedConcerns || [],
    guardStops: evidence.guardStops || [],
    budgetExhaustedAt: evidence.budgetExhaustedAt || null,
    // headless-autonomy D4/D6 + acceptance 4 — NULLABLE, alongside `resolveMode` /
    // `budgetExhaustedAt` (the resolve-to-clean precedent). `autonomyMode` says which mode
    // produced this record. `parked` carries the serialized PARK: state, the pending
    // question, its context, and `recordSerialized` — whether this park's OWN record was
    // written, which is false exactly at the loud attestation park, whose reason for
    // existing is that the write could not be confirmed. `terminalState` is the TOP-LEVEL,
    // greppable answer to "did this run park?": the record's `verdict` deliberately stays
